CREATE OR REPLACE FUNCTION public.moored_post(p_world uuid, b placed)
 RETURNS placed
 LANGUAGE sql
 STABLE
AS $function$
  select pl.* from placed pl
   where pl.world_id = p_world and pl.kind = 'furniture' and pl.sub = mooring_post_kind()
